import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { ClienteService, Cliente } from '../cliente.service';

@Component({
  selector: 'app-cliente-list',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './cliente-list.component.html',
  styleUrls: ['./cliente-list.component.css'],
})
export class ClienteListComponent implements OnInit {
  clientes: Cliente[] = [];
  loading = true;
  error = '';

  constructor(
    private clienteService: ClienteService,
    private router: Router,
  ) {}

  ngOnInit() {
    this.cargarClientes();
  }

  cargarClientes() {
    this.loading = true;
    this.error = '';
    this.clienteService.listar().subscribe({
      next: (data) => {
        this.clientes = data;
        this.loading = false;
      },
      error: (err) => {
        this.error = 'Error al cargar clientes';
        this.loading = false;
      },
    });
  }

  crear() {
    this.router.navigate(['/clientes/nuevo']);
  }

  editar(id: number) {
    this.router.navigate(['/clientes', id, 'editar']);
  }

  eliminar(id: number) {
    if (confirm('¿Deseas eliminar este cliente?')) {
      this.clienteService.eliminar(id).subscribe({
        next: () => {
          this.cargarClientes();
        },
        error: () => {
          this.error = 'Error al eliminar cliente';
        },
      });
    }
  }

  ver(id: number) {
    this.router.navigate(['/clientes', id]);
  }
}
<div class="container">
  <div class="header">
    <h2>Clientes</h2>
    <button class="btn btn-primary" (click)="crear()">+ Nuevo Cliente</button>
  </div>

  <div *ngIf="error" class="alert alert-danger">
    {{ error }}
  </div>

  <div *ngIf="loading" class="loading">
    Cargando clientes...
  </div>

  <div *ngIf="!loading && clientes.length > 0" class="table-container">
    <table class="table">
      <thead>
        <tr>
          <th>Código</th>
          <th>Nombre</th>
          <th>Teléfono</th>
          <th>Correo</th>
          <th>Dirección</th>
          <th>Acciones</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let cliente of clientes">
          <td>{{ cliente.codigo }}</td>
          <td>{{ cliente.nombre }}</td>
          <td>{{ cliente.telefono }}</td>
          <td>{{ cliente.correo }}</td>
          <td>{{ cliente.direccion }}</td>
          <td>
            <button class="btn btn-sm btn-info" (click)="ver(cliente.id_cliente!)">Ver</button>
            <button class="btn btn-sm btn-warning" (click)="editar(cliente.id_cliente!)">Editar</button>
            <button class="btn btn-sm btn-danger" (click)="eliminar(cliente.id_cliente!)">Eliminar</button>
          </td>
        </tr>
      </tbody>
    </table>
  </div>

  <div *ngIf="!loading && clientes.length === 0" class="empty-state">
    <p>No hay clientes. <a (click)="crear()">Crear uno nuevo</a></p>
  </div>
</div>
